/**
 * Bulk-import persistence: the replay record per workspace key, and the write
 * that turns one checked batch into labels, issues and that record.
 *
 * Must call (do not reimplement): orgPredicate, toIssue, parseJsonArray, brandId
 */
import { and, eq, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, issueImports, issueLabels, issues, labels } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { brandId, parseJsonArray, toIssue } from "./_mappers";
import type { ImportIssueRowInput } from "@/schemas/issue-import";
import type {
  IssueId,
  LabelId,
  OrgId,
  ProjectId,
  UserId,
} from "@/types/common";
import type { Issue } from "@/types/issue";

/** What a workspace key was first used for. */
export interface IssueImportRecord {
  readonly projectId: ProjectId;
  readonly issueIds: readonly IssueId[];
}

/** One validated row, with its assignee already matched to a live member. */
export interface PreparedImportRow {
  readonly row: ImportIssueRowInput;
  readonly assigneeId: UserId | null;
}

export interface ImportBatch {
  readonly orgId: OrgId;
  readonly projectId: ProjectId;
  readonly importKey: string;
  readonly importerId: UserId;
  readonly rows: readonly PreparedImportRow[];
}

/** A replay carries the first import's record; a first upload its new issues. */
export type ImportCommit =
  | { readonly replayed: true; readonly record: IssueImportRecord }
  | { readonly replayed: false; readonly issues: readonly Issue[] };

export async function findIssueImport(
  orgId: OrgId,
  importKey: string,
): Promise<IssueImportRecord | null> {
  const row = getDb()
    .select()
    .from(issueImports)
    .where(
      and(
        orgPredicate(issueImports.orgId, orgId),
        eq(issueImports.importKey, importKey),
      ),
    )
    .get();
  return row ? toImportRecord(row) : null;
}

/**
 * Writes the batch or nothing. It runs synchronously inside one transaction, so
 * the replay check, label creation, numbering and every insert see one state —
 * and a concurrent upload of the same key cannot slip past the check.
 */
export function commitIssueImport(batch: ImportBatch): ImportCommit {
  return getDb().transaction((tx): ImportCommit => {
    const prior = tx
      .select()
      .from(issueImports)
      .where(
        and(
          orgPredicate(issueImports.orgId, batch.orgId),
          eq(issueImports.importKey, batch.importKey),
        ),
      )
      .get();
    if (prior) return { replayed: true, record: toImportRecord(prior) };

    const stamp = toIsoTimestamp(new Date());

    const labelIdByName = new Map(
      tx
        .select({ id: labels.id, name: labels.name })
        .from(labels)
        .where(orgPredicate(labels.orgId, batch.orgId))
        .all()
        .map((label) => [label.name, brandId<LabelId>(label.id)] as const),
    );

    /** Labels named for the first time are created once, with the defaults. */
    const labelIdFor = (name: string): LabelId => {
      const known = labelIdByName.get(name);
      if (known !== undefined) return known;

      const id = brandId<LabelId>(newId());
      tx.insert(labels)
        .values({
          id,
          orgId: batch.orgId,
          name,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .run();
      labelIdByName.set(name, id);
      return id;
    };

    const highest = tx
      .select({ value: sql<number | null>`max(${issues.number})` })
      .from(issues)
      .where(
        and(
          orgPredicate(issues.orgId, batch.orgId),
          eq(issues.projectId, batch.projectId),
        ),
      )
      .get();
    const firstNumber = (highest?.value ?? 0) + 1;

    const created = batch.rows.map(({ row, assigneeId }, index) => {
      const labelIds = [...new Set(row.labels)].map((name) => labelIdFor(name));

      const issue = tx
        .insert(issues)
        .values({
          id: newId(),
          orgId: batch.orgId,
          projectId: batch.projectId,
          number: firstNumber + index,
          title: row.title,
          description: row.description,
          status: row.status,
          priority: row.priority,
          authorId: batch.importerId,
          assigneeId,
          parentId: null,
          estimate: null,
          dueAt: row.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .returning()
        .get();

      if (labelIds.length > 0) {
        tx.insert(issueLabels)
          .values(
            labelIds.map((labelId) => ({
              orgId: batch.orgId,
              issueId: issue.id,
              labelId,
            })),
          )
          .run();
      }

      return toIssue(issue, labelIds);
    });

    tx.insert(issueImports)
      .values({
        id: newId(),
        orgId: batch.orgId,
        importKey: batch.importKey,
        projectId: batch.projectId,
        importedBy: batch.importerId,
        issueIds: JSON.stringify(created.map((issue) => issue.id)),
        createdAt: stamp,
        updatedAt: stamp,
      })
      .run();

    return { replayed: false, issues: created };
  });
}

function toImportRecord(row: typeof issueImports.$inferSelect): IssueImportRecord {
  return {
    projectId: brandId<ProjectId>(row.projectId),
    issueIds: parseJsonArray<IssueId>(row.issueIds),
  };
}

