/**
 * Bulk import: every row becomes an issue in the project, in file order, or
 * none does. The gates run in `createIssue`'s order — tenant scope, the project
 * and its archive state, `issue:create` — then the replay lookup, the
 * per-project quota for the whole batch and the rate allowance (one unit per
 * row). Nothing is written until they all pass, and the write is one
 * transaction. A success publishes a single `issues.imported`; the batch is
 * not announced per issue.
 */
export async function importIssues(
  actor: Actor,
  input: ImportIssuesInput,
): Promise<IssueImportResult> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const replay = await issueImportRepo.findIssueImport(
    input.orgId,
    input.importKey,
  );
  if (replay) return replayedImport(input, replay);

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  assertIssueQuota(org.plan, project, used, input.rows.length);

  const verdict = await consumeRateLimit(
    input.orgId,
    ISSUE_CREATE_BUCKET,
    input.rows.length,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Issue creation rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const assigneeEmails = input.rows.flatMap((row) =>
    row.assigneeEmail === null ? [] : [row.assigneeEmail],
  );
  const assigneeIds = await memberRepo.findActiveMemberIdsByEmail(
    input.orgId,
    assigneeEmails,
  );

  const commit = issueImportRepo.commitIssueImport({
    orgId: input.orgId,
    projectId: input.projectId,
    importKey: input.importKey,
    importerId: actor.userId,
    rows: input.rows.map((row) => ({
      row,
      assigneeId:
        row.assigneeEmail === null
          ? null
          : (assigneeIds.get(row.assigneeEmail.toLowerCase()) ?? null),
    })),
  });
  if (commit.replayed) return replayedImport(input, commit.record);

  await emit("issues.imported", {
    ...actorEnvelope(actor),
    projectId: input.projectId,
    importKey: input.importKey,
    issueIds: commit.issues.map((issue) => issue.id),
  });

  return {
    importKey: input.importKey,
    projectId: input.projectId,
    issues: commit.issues,
    replayed: false,
  };
}

/** The first import's issues, in their original order, flagged as a replay. */
async function replayedImport(
  input: ImportIssuesInput,
  record: IssueImportRecord,
): Promise<IssueImportResult> {
  return {
    importKey: input.importKey,
    projectId: record.projectId,
    issues: await issueRepo.listIssuesByIds(input.orgId, record.issueIds),
    replayed: true,
  };
}

/**
 * The per-project quota gate shared by a single create and a batch import, so
 * both refuse with the same error.
 */
function assertIssueQuota(
  plan: PlanId,
  project: Project,
  used: number,
  requested = 1,
): void {
  if (wouldExceedLimit(plan, "issuesPerProject", used, requested)) {
    throw new Error(
      `Plan ${plan} allows no more issues in project ${project.key}`,
    );
  }
}

