/**
 * Bulk issue import: authorization, the all-or-nothing quota and rate gates,
 * row mapping, replays, and the single batch announcement the listeners read.
 * The start-up handlers are attached the way the server attaches them.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import { NotFoundError } from "@/server/services/_support";
import * as activityService from "@/server/services/activity-service";
import { registerEventHandlers, unregisterEventHandlers } from "@/server/services/event-registry";
import * as issueService from "@/server/services/issue-service";
import * as labelService from "@/server/services/label-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import * as usageService from "@/server/services/usage-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { ImportIssueRowInput } from "@/schemas/issue-import";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

function row(title: string, overrides: Partial<ImportIssueRowInput> = {}): ImportIssueRowInput {
  return {
    title,
    description: null,
    status: "backlog",
    priority: "none",
    assigneeEmail: null,
    labels: [],
    dueAt: null,
    ...overrides,
  };
}

function batch(tenant: Tenant, importKey: string, rows: readonly ImportIssueRowInput[]) {
  return { orgId: tenant.org.id, projectId: tenant.project.id, importKey, rows: [...rows] };
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  registerEventHandlers();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  unregisterEventHandlers();
  cleanup();
});

describe("services/issue-service importIssues", () => {
  it("creates every row in file order, authored by the importer, with the row's fields", async () => {
    const tenant = await createTenant("imp-order");
    const dueAt = "2026-11-01T09:00:00.000Z" as ImportIssueRowInput["dueAt"];

    const result = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, "import-order-0001", [
        row("First row", { description: "Body", status: "todo", priority: "high", dueAt }),
        row("Second row"),
        row("Third row", { status: "in_review" }),
      ]),
    );

    expect(result.replayed).toBe(false);
    expect(result.projectId).toBe(tenant.project.id);
    expect(result.issues.map((issue) => issue.title)).toEqual([
      "First row",
      "Second row",
      "Third row",
    ]);
    expect(result.issues.map((issue) => issue.number)).toEqual([1, 2, 3]);

    const [first] = result.issues;
    expect(first).toMatchObject({
      description: "Body",
      status: "todo",
      priority: "high",
      dueAt,
      authorId: tenant.userIds.member,
      parentId: null,
      estimate: null,
      assigneeId: null,
    });
    expect(result.issues[2]?.status).toBe("in_review");
  });

  it("publishes one issues.imported for the batch and no per-issue announcements", async () => {
    const tenant = await createTenant("imp-events");
    const imported = capture("issues.imported");
    const created = capture("issue.created");

    const result = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, "import-events-0001", [row("Alpha one"), row("Beta two")]),
    );

    expect(created).toHaveLength(0);
    expect(imported).toHaveLength(1);
    expect(imported[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.member,
      projectId: tenant.project.id,
      importKey: "import-events-0001",
      issueIds: result.issues.map((issue) => issue.id),
    });

    const feed = await activityService.listActivity(tenant.actors.admin, {
      orgId: tenant.org.id,
      limit: 100,
      cursor: null,
    });
    const entries = feed.items.filter((event) => event.action === "issues.imported");
    expect(entries).toHaveLength(1);
    expect(entries[0]).toMatchObject({
      actorId: tenant.userIds.member,
      subjectKind: "project",
      subjectId: tenant.project.id,
      projectId: tenant.project.id,
      metadata: { count: 2, importKey: "import-events-0001" },
    });
    expect(feed.items.filter((event) => event.action === "issue.created")).toHaveLength(0);
  });

  it("makes the imported issues searchable and counts them in the usage meter", async () => {
    const tenant = await createTenant("imp-reach");

    await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, "import-reach-0001", [
        row("Zebrafish migration plan"),
        row("Zebrafish rollout notes"),
      ]),
    );

    const hits = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "zebrafish",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(hits.total).toBe(2);

    const usage = await usageService.getUsage(tenant.actors.admin, tenant.org.id);
    expect(usage.issuesUsed).toBe(2);
    const recounted = await usageService.recomputeUsage(tenant.org.id);
    expect(recounted.issuesUsed).toBe(usage.issuesUsed);
  });

  it("replays the first import for a reused key, creating nothing and announcing nothing", async () => {
    const tenant = await createTenant("imp-replay");
    const first = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, "import-replay-0001", [row("Original one"), row("Original two")]),
    );

    const imported = capture("issues.imported");
    const replay = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, "import-replay-0001", [row("Different rows entirely")]),
    );

    expect(replay.replayed).toBe(true);
    expect(replay.issues.map((issue) => issue.id)).toEqual(first.issues.map((issue) => issue.id));
    expect(replay.issues.map((issue) => issue.title)).toEqual(["Original one", "Original two"]);
    expect(imported).toHaveLength(0);
    expect(await issueRepo.countIssues(tenant.org.id, tenant.project.id)).toBe(2);
  });

  it("treats identical rows under a different key as a new import", async () => {
    const tenant = await createTenant("imp-newkey");
    const rows = [row("Same content")];

    const first = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, "import-newkey-0001", rows),
    );
    const second = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, "import-newkey-0002", rows),
    );

    expect(second.replayed).toBe(false);
    expect(second.issues[0]?.id).not.toBe(first.issues[0]?.id);
    expect(second.issues[0]?.number).toBe(2);
  });

  it("scopes keys to the workspace", async () => {
    const tenantA = await createTenant("imp-keys-a");
    const tenantB = await createTenant("imp-keys-b");

    await issueService.importIssues(
      tenantA.actors.member,
      batch(tenantA, "import-shared-key", [row("Workspace A row")]),
    );
    const other = await issueService.importIssues(
      tenantB.actors.member,
      batch(tenantB, "import-shared-key", [row("Workspace B row")]),
    );

    expect(other.replayed).toBe(false);
    expect(other.issues.map((issue) => issue.title)).toEqual(["Workspace B row"]);
  });

  it("refuses a batch that would pass the project quota, creating nothing and keeping the key free", async () => {
    const quotaTenant = await createTenant("imp-quota", "free");

    for (let number = 1; number <= 98; number += 1) {
      await issueRepo.insertIssue(
        issueInput(quotaTenant.org.id, quotaTenant.project.id, { title: `Seed ${number}` }),
        quotaTenant.actors.member.userId,
        number,
      );
    }

    await expect(
      issueService.importIssues(
        quotaTenant.actors.member,
        batch(quotaTenant, "import-quota-0001", [row("One"), row("Two"), row("Three")]),
      ),
    ).rejects.toThrow(/allows no more issues/);
    expect(await issueRepo.countIssues(quotaTenant.org.id, quotaTenant.project.id)).toBe(98);

    const fits = await issueService.importIssues(
      quotaTenant.actors.member,
      batch(quotaTenant, "import-quota-0001", [row("One"), row("Two")]),
    );
    expect(fits.replayed).toBe(false);
    expect(await issueRepo.countIssues(quotaTenant.org.id, quotaTenant.project.id)).toBe(100);
  });

  it("refuses a batch the rate allowance does not cover, spending nothing", async () => {
    const rateTenant = await createTenant("imp-rate", "free");
    const sixtyOne = Array.from({ length: 61 }, (_, index) => row(`Row number ${index + 1}`));

    await expect(
      issueService.importIssues(
        rateTenant.actors.member,
        batch(rateTenant, "import-rate-0001", sixtyOne),
      ),
    ).rejects.toThrow(/rate limit/);
    expect(await issueRepo.countIssues(rateTenant.org.id, rateTenant.project.id)).toBe(0);

    const sixty = sixtyOne.slice(0, 60);
    const accepted = await issueService.importIssues(
      rateTenant.actors.member,
      batch(rateTenant, "import-rate-0001", sixty),
    );
    expect(accepted.issues).toHaveLength(60);
  });

  it("matches assignees case-insensitively among live members only", async () => {
    const tenant = await createTenant("imp-assign");
    const viewerMembership = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!viewerMembership) throw new Error("viewer membership missing");
    await memberRepo.archiveMember(tenant.org.id, viewerMembership.id);

    const result = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, "import-assign-0001", [
        row("Mixed case", { assigneeEmail: "MEMBER@imp-assign.test" as never }),
        row("Removed member", { assigneeEmail: "viewer@imp-assign.test" }),
        row("Outsider", { assigneeEmail: "stranger@elsewhere.test" }),
        row("Admin", { assigneeEmail: "admin@imp-assign.test" }),
      ]),
    );

    expect(result.issues.map((issue) => issue.assigneeId)).toEqual([
      tenant.userIds.member,
      null,
      null,
      tenant.userIds.admin,
    ]);
  });

